def _alive(pid: int) -> bool:
    if pid <= 0:
        return False
    if os.name != "nt":
        try:
            os.kill(pid, 0)
        except OSError:
            return False
        return True
    import ctypes

    handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
    if not handle:
        return False
    ctypes.windll.kernel32.CloseHandle(handle)
    return True


def _pid_listening(port: int) -> int | None:
    completed = subprocess.run(
        ["netstat", "-ano", "-p", "tcp"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        creationflags=_NO_WINDOW,
        check=False,
    )
    token = f":{port}"
    for line in completed.stdout.splitlines():
        if "LISTENING" not in line or token not in line:
            continue
        parts = line.split()
        try:
            return int(parts[-1])
        except (ValueError, IndexError):
            continue
    return None


def _signal_stop(pid: int) -> None:
    if os.name != "nt":
        try:
            os.kill(pid, signal.SIGTERM)
        except OSError:
            return
        return
    try:
        os.kill(pid, signal.CTRL_BREAK_EVENT)
    except OSError:
        _terminate(pid)


def _terminate(pid: int) -> None:
    if os.name != "nt":
        try:
            os.kill(pid, signal.SIGKILL)
        except OSError:
            return
        return
    import ctypes

    handle = ctypes.windll.kernel32.OpenProcess(0x0001, False, pid)
    if not handle:
        return
    ctypes.windll.kernel32.TerminateProcess(handle, 1)
    ctypes.windll.kernel32.CloseHandle(handle)


def _assign_job(pid: int, handle) -> None:
    """End this process when Houdini's process handle closes, even if killed."""
    if os.name != "nt":
        return
    job = _job_handle()
    if job is None:
        return
    import ctypes

    kernel = ctypes.windll.kernel32
    opened = None
    if not handle:
        handle = kernel.OpenProcess(0x0100 | 0x0001, False, pid)
        opened = handle
    if not handle:
        return
    kernel.AssignProcessToJobObject(job, int(handle))
    if opened:
        kernel.CloseHandle(opened)


def _job_handle():
    global _JOB
    if _JOB:
        return _JOB
    if os.name != "nt":
        return None
    import ctypes

    kernel = ctypes.windll.kernel32

    class Basic(ctypes.Structure):
        _fields_ = [
            ("PerProcessUserTimeLimit", ctypes.c_int64),
            ("PerJobUserTimeLimit", ctypes.c_int64),
            ("LimitFlags", ctypes.c_uint32),
            ("MinimumWorkingSetSize", ctypes.c_size_t),
            ("MaximumWorkingSetSize", ctypes.c_size_t),
            ("ActiveProcessLimit", ctypes.c_uint32),
            ("Affinity", ctypes.c_size_t),
            ("PriorityClass", ctypes.c_uint32),
            ("SchedulingClass", ctypes.c_uint32),
        ]

    class Counters(ctypes.Structure):
        _fields_ = [
            ("ReadOperationCount", ctypes.c_uint64),
            ("WriteOperationCount", ctypes.c_uint64),
            ("OtherOperationCount", ctypes.c_uint64),
            ("ReadTransferCount", ctypes.c_uint64),
            ("WriteTransferCount", ctypes.c_uint64),
            ("OtherTransferCount", ctypes.c_uint64),
        ]

    class Extended(ctypes.Structure):
        _fields_ = [
            ("BasicLimitInformation", Basic),
            ("IoInfo", Counters),
            ("ProcessMemoryLimit", ctypes.c_size_t),
            ("JobMemoryLimit", ctypes.c_size_t),
            ("PeakProcessMemoryUsed", ctypes.c_size_t),
            ("PeakJobMemoryUsed", ctypes.c_size_t),
        ]

    job = kernel.CreateJobObjectW(None, None)
    if not job:
        return None
    info = Extended()
    info.BasicLimitInformation.LimitFlags = 0x2000
    if not kernel.SetInformationJobObject(job, 9, ctypes.byref(info), ctypes.sizeof(info)):
        kernel.CloseHandle(job)
        return None
    _JOB = job
    return job

