def _fold(events: list[dict]) -> list[dict]:
    """One card per open. A later Saved, Restored, or Not saved replaces Saving."""
    folded: list[dict] = []
    for item in events:
        if item.get("state") == "working" or not item.get("node"):
            folded.append(item)
            continue
        for index in range(len(folded) - 1, -1, -1):
            prior = folded[index]
            if prior.get("node") != item["node"]:
                continue
            if prior.get("state") == "working":
                folded[index] = item
                break
            folded.append(item)
            break
        else:
            folded.append(item)
    return folded

