def _opening_usage(model: bool) -> dict:
    if model:
        return pending_pick(os.environ.get("HOUDINI_WIZARD_MODEL", DEFAULT_MODEL))
    return {}


def _settled_usage(request: dict, model: bool, card: dict, elapsed: int, fallback: dict | None = None) -> dict:
    usage = dict(card.get("usage") or fallback or {})
    if not usage:
        logged = _log_card(request)
        if model or logged.get("needs_model"):
            usage = skipped("pick a heading", "Gemma did not answer.")
        elif logged.get("known_heading"):
            usage = skipped("quote the heading", "The heading was already named, so Gemma was not asked.")
        else:
            usage = skipped("open the node", "No cook error named a heading, so Gemma was not asked.")
    usage["save_ms"] = elapsed
    return usage

